if pos < 0: raise SystemExit('database insert anchor missing')
d = d[:pos] + '''    fun searchChatJson(chatId: Long, query: String, limit: Int): String {\n        val q = query.trim(); if (q.isEmpty()) return "[]"; val a = JSONArray()\n        readableDatabase.rawQuery("SELECT m.id, m.chat_id, c.name, m.sender, m.date_unix, m.text FROM messages m JOIN chats c ON c.id=m.chat_id WHERE m.chat_id=? AND m.text LIKE ? ORDER BY m.date_unix DESC, m.id DESC LIMIT ?", arrayOf(chatId.toString(), "%$q%", limit.coerceIn(1, 500).toString())).use { cur -> while (cur.moveToNext()) a.put(JSONObject().put("messageDbId", cur.getLong(0)).put("chatId", cur.getLong(1)).put("chatName", cur.getString(2) ?: "Chat").put("sender", cur.getString(3) ?: "").put("dateUnix", cur.getLong(4)).put("text", cur.getString(5) ?: "")) }; return a.toString()\n    }\n    fun newerMessagesJson(chatId: Long, limit: Int, afterDbId: Long): String { val a = JSONArray(); readableDatabase.rawQuery("SELECT id, message_id, sender, date_unix, text, media_path, mime_type, reply_to, forwarded_from, edited FROM messages WHERE chat_id=? AND id>? ORDER BY id ASC LIMIT ?", arrayOf(chatId.toString(), afterDbId.toString(), limit.coerceIn(1, 500).toString())).use { cur -> while (cur.moveToNext()) a.put(messageJsonFromCursor(cur, chatId)) }; return a.toString() }\n    fun hasOlder(chatId: Long, dbId: Long): Boolean = readableDatabase.rawQuery("SELECT 1 FROM messages WHERE chat_id=? AND id<? LIMIT 1", arrayOf(chatId.toString(), dbId.toString())).use { it.moveToFirst() }\n    fun hasNewer(chatId: Long, dbId: Long): Boolean = readableDatabase.rawQuery("SELECT 1 FROM messages WHERE chat_id=? AND id>? LIMIT 1", arrayOf(chatId.toString(), dbId.toString())).use { it.moveToFirst() }\n    private fun messageJsonFromCursor(cur: Cursor, chatId: Long): JSONObject {\n        val sender = cur.getString(2) ?: ""\n        val isMine = readableDatabase.rawQuery("SELECT owner_user_id FROM archives a JOIN chats c ON c.archive_id=a.id WHERE c.id=?", arrayOf(chatId.toString())).use { owner -> owner.moveToFirst() && (owner.getString(0)?.let { ownerId -> sender.contains(ownerId.removePrefix("user"), ignoreCase = true) } == true) }\n        return JSONObject().put("dbId", cur.getLong(0)).put("telegramId", if (cur.isNull(1)) JSONObject.NULL else cur.getLong(1)).put("sender", sender).put("mine", isMine).put("dateUnix", cur.getLong(3)).put("text", cur.getString(4) ?: "").put("mediaPath", cur.getString(5)).put("mimeType", cur.getString(6)).put("replyTo", if (cur.isNull(7)) JSONObject.NULL else cur.getLong(7)).put("forwardedFrom", cur.getString(8)).put("edited", cur.getString(9))\n    }\n\n''' + d[pos:]
db.write_text(d, encoding='utf-8')

(root / 'app/src/main/java/com/tarjs/archive/AppPasscode.kt').write_text('''package com.tarjs.archive\nimport android.content.Context\nimport android.util.Base64\nimport java.security.MessageDigest\nimport java.security.SecureRandom\nimport javax.crypto.SecretKeyFactory\nimport javax.crypto.spec.PBEKeySpec\nclass AppPasscode(context: Context) {\n private val prefs=context.getSharedPreferences("tarjs_app_lock",Context.MODE_PRIVATE)\n fun isSet()=prefs.contains("hash")&&prefs.contains("salt")\n fun set(passcode:String){ require(passcode.length>=4); val salt=ByteArray(16).also{SecureRandom().nextBytes(it)}; prefs.edit().putString("salt",Base64.encodeToString(salt,Base64.NO_WRAP)).putString("hash",hash(passcode,salt)).apply() }\n fun verify(passcode:String):Boolean{ val salt=prefs.getString("salt",null)?.let{Base64.decode(it,Base64.NO_WRAP)}?:return false; val expected=prefs.getString("hash",null)?:return false; return MessageDigest.isEqual(expected.toByteArray(),hash(passcode,salt).toByteArray()) }\n private fun hash(passcode:String,salt:ByteArray):String{ val spec=PBEKeySpec(passcode.toCharArray(),salt,120_000,256); val bytes=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).encoded; spec.clearPassword(); return Base64.encodeToString(bytes,Base64.NO_WRAP) }\n}\n''', encoding='utf-8')

s = ui.read_text(encoding='utf-8'); idx=s.index('@Composable\nfun TarJsRoot(controller: TarJsController) {')
gate='''@Composable\nprivate fun TarJsAppPasscodeGate(content: @Composable () -> Unit) {\n val context=LocalContext.current; val store=remember{AppPasscode(context)}; var unlocked by remember{mutableStateOf(false)}; var creating by remember{mutableStateOf(!store.isSet())}; var passcode by remember{mutableStateOf("")}; var confirm by remember{mutableStateOf("")}; var error by remember{mutableStateOf("")}\n if(unlocked){content();return}; BackHandler{(context as? Activity)?.finish()}\n Box(Modifier.fillMaxSize().padding(WindowInsets.safeDrawing.asPaddingValues()),contentAlignment=Alignment.Center){ Card(Modifier.fillMaxWidth().padding(24.dp),shape=RoundedCornerShape(28.dp)){ Column(Modifier.padding(24.dp),horizontalAlignment=Alignment.CenterHorizontally){ Icon(Icons.Default.Lock,null,Modifier.size(48.dp),tint=MaterialTheme.colorScheme.primary); Spacer(Modifier.height(16.dp)); Text(if(creating)"Protect your chats" else "Unlock TAR-JS",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold); Spacer(Modifier.height(18.dp)); OutlinedTextField(passcode,{passcode=it;error=""},label={Text(if(creating)"New passcode" else "Passcode")},singleLine=true,visualTransformation=PasswordVisualTransformation()); if(creating){Spacer(Modifier.height(10.dp));OutlinedTextField(confirm,{confirm=it;error=""},label={Text("Confirm passcode")},singleLine=true,visualTransformation=PasswordVisualTransformation())}; if(error.isNotBlank()){Text(error,color=MaterialTheme.colorScheme.error)}; Spacer(Modifier.height(18.dp)); Button(onClick={if(creating){if(passcode.length<4)error="Use at least 4 characters" else if(passcode!=confirm)error="Passcodes do not match" else runCatching{store.set(passcode);unlocked=true}.onFailure{error=it.message?:"Could not set passcode"}}else{if(store.verify(passcode))unlocked=true else error="Incorrect passcode"}},modifier=Modifier.fillMaxWidth()){Text(if(creating)"Set passcode" else "Unlock")} } } }\n}\n\n'''
s=s[:idx]+gate+s[idx:]; ui.write_text(s,encoding='utf-8')

