test.write_text(r'''package com.tarjs.archive\nimport androidx.test.core.app.ApplicationProvider\nimport org.json.JSONArray\nimport org.junit.*\nimport org.junit.runner.RunWith\nimport org.robolectric.RobolectricTestRunner\nimport org.robolectric.annotation.Config\n@RunWith(RobolectricTestRunner::class) @Config(sdk=[30]) class SearchPagingIntegrationTest {\n private val ctx get()=ApplicationProvider.getApplicationContext<android.content.Context>(); private lateinit var db:ArchiveDatabase\n @Before fun setup(){ctx.deleteDatabase("tarjs.db");db=ArchiveDatabase(ctx)}; @After fun teardown(){db.close();ctx.deleteDatabase("tarjs.db")}\n @Test fun searchScopedAndNewerPagingWorks(){ val a=db.createArchive("A","test",null); val c1=db.upsertChat(a,100,"Alice","personal_chat"); val c2=db.upsertChat(a,200,"Bob","personal_chat"); for(i in 1..240)db.insertMessage(c1,i.toLong(),"Alice",i.toLong(),if(i==10)"needle old" else "Alice $i",null,null,null,null,null,false); db.insertMessage(c2,1,"Bob",1,"needle other",null,null,null,null,null,false); val hits=JSONArray(db.searchChatJson(c1,"needle",20)); Assert.assertEquals(1,hits.length()); Assert.assertEquals(c1,hits.getJSONObject(0).getLong("chatId")); val target=hits.getJSONObject(0).getLong("messageDbId"); val window=JSONArray(db.messageWindowJson(c1,target)); val last=window.getJSONObject(window.length()-1).getLong("dbId"); Assert.assertTrue(db.hasNewer(c1,last)); Assert.assertTrue(JSONArray(db.newerMessagesJson(c1,50,last)).length()>0) }\n}\n''',encoding='utf-8')

